 /// paleta: «purple», «mint»…), nunca una ruta ni una URL. Nulo = sin elegir:\n  /// iniciales sobre un color derivado del id. Lo valida la API (utils/avatars.ts).\n  avatar             String?\n  createdAt          DateTime        @default(now()) @map(\"created_at\")\n  updatedAt          DateTime        @updatedAt @map(\"updated_at\")\n\n  // Relations\n  createdBy            User?                    @relation(\"CreatedUsers\", fields: [createdById], references: [id], onDelete: SetNull)\n  createdUsers         User[]                   @relation(\"CreatedUsers\")\n  homeClass            Class?                   @relation(\"HomeClassStudents\", fields: [homeClassId], references: [id], onDelete: SetNull)\n  refreshTokens        RefreshToken[]\n  teacherClasses       Class[]                  @relation(\"TeacherClasses\")\n  trashedClasses       Class[]                  @relation(\"TrashedClasses\")\n  recommendedTemplates Class[]                  @relation(\"RecommendedTemplates\")\n  enrollments          ClassEnrollment[]\n  createdBadges        Badge[]                  @relation(\"CreatedBadges\")\n  earnedBadges         StudentBadge[]\n  missionProgress      StudentMissionProgress[]\n  enigmaProgress       StudentEnigmaProgress[]\n  notifications        Notification[]\n  activities           Activity[]\n  conversations        ChatConversation[]\n  joinRequests         JoinRequest[]\n  sentInvitations      Invitation[]             @relation(\"SentInvitations\")\n  receivedInvitations  Invitation[]             @relation(\"ReceivedInvitations\")\n  submissions          EnigmaSubmission[]       @relation(\"StudentSubmissions\")\n  settings             UserSettings?\n  shopPurchases        ShopPurchase[]\n  shopItemUses         ShopItemUse[]\n  missionHintUses      MissionHintUse[]\n  behaviorsApplied     BehaviorApplication[]    @relation(\"BehaviorTeacher\")\n  submissionsReviewed  EnigmaSubmission[]       @relation(\"SubmissionReviewer\")\n  activitiesActed      Act